{
   rt_bars = new RtBar[n > 0 ? n : 1]; rt_n = n; rt_tick = tick; _Digits = digits; _Point = tick;
   for(int i = 0; i < n; i++) { rt_bars[i].t = t[i]; rt_bars[i].o = o[i]; rt_bars[i].h = h[i]; rt_bars[i].l = l[i]; rt_bars[i].c = c[i]; }
}

