double iHigh(const string&, ENUM_TIMEFRAMES, int s) { return s < 0 || s >= rt_n ? 0 : rt_bars[rt_n - 1 - s].h; }
double iLow(const string&, ENUM_TIMEFRAMES, int s) { return s < 0 || s >= rt_n ? 0 : rt_bars[rt_n - 1 - s].l; }
